import {buildIndex,certify,scores,normalize} from './engine.mjs';
import {finitePool,matchFiniteQuery,subsetIndex} from './pool.mjs';
let index,dictionary,modelHash,corpusHash,activePool,poolIndex;
async function hash(x){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(x)));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function attach(result){return {...result,modelHash,corpusHash,computedAt:new Date().toISOString()}}
self.onmessage=async({data:m})=>{try{
 if(m.type==='init'){activePool=null;poolIndex=null;index=buildIndex(m.documents);dictionary=m.dictionary||{};corpusHash=await hash(index.docs);modelHash=await hash({version:index.version,weights:index.weights.map(w=>[...w])});postMessage({type:'ready',documents:index.n,features:index.features,modelHash,corpusHash})}
 else if(m.type==='query'){if(!index)throw Error('Chỉ mục chưa sẵn sàng.');activePool=null;poolIndex=null;const result=attach(certify(index,m.query,{...m.options,dictionary,audit:true,enumeration:{collect:true}}));const pool=finitePool(result.factorScores,result.budget,10);result.possibleTopKPool={...pool,documentIds:pool.pool.map(j=>index.docs[j].id),modelHash,corpusHash,query:result.query,channel:result.channel,budget:result.budget};poolIndex=subsetIndex(index,pool.pool);activePool=result;postMessage({type:'result',result})}
 else if(m.type==='pool-replay'){if(!activePool||!poolIndex||m.modelHash!==modelHash||m.corpusHash!==corpusHash||m.baseQuery!==activePool.query)throw Error('Pool đã hết hiệu lực. Chạy lại chứng nhận với corpus và truy vấn hiện tại.');const query=normalize(m.query),choices=matchFiniteQuery(activePool.forms,activePool.budget,query);if(!choices)throw Error('Truy vấn này nằm ngoài lattice/ngân sách đã chứng nhận. Hãy chạy chứng nhận mới.');const start=performance.now(),z=Array.from(scores(poolIndex,query)),k=activePool.possibleTopKPool.k,cut=z.slice().sort((a,b)=>b-a)[k-1],ids=z.flatMap((v,j)=>v>=cut?[poolIndex.docs[j].id]:[]);postMessage({type:'pool-replay',query,choices,ids,poolDocuments:poolIndex.n,elapsedMs:performance.now()-start,modelHash,corpusHash})}
 else if(m.type==='batch'){if(!index)throw Error('Chỉ mục chưa sẵn sàng.');const results=[];for(let i=0;i<m.queries.length;i++){const result=attach(certify(index,m.queries[i],{...m.options,dictionary,audit:true,enumeration:{collect:true}}));results.push(result);postMessage({type:'progress',done:i+1,total:m.queries.length});await new Promise(r=>setTimeout(r,0))}postMessage({type:'batch',results})}
 else if(m.type==='bundle')postMessage({type:'bundle',kind:m.kind,requestId:m.requestId,corpus:index.docs,weights:index.weights.map(w=>[...w]),corpusHash,modelHash});
}catch(e){postMessage({type:'error',message:e.message||String(e)})}};
